#!/usr/bin/env python3
"""Writes data/destinations.json for Wayward Bike: the starter set of ~60 places and routes.

Edit the lists below and re-run:  python3 scripts/build_destinations.py
A destination is a place you'd base a trip around (or, for multi-day routes, the route itself, with its
dot near the middle). `children` are distinct riding areas or famous climbs inside it, each with short stats.
"""
import json, os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

ABOUT = ("Curated seed list for Wayward Bike. Each destination is one of two kinds. "
         "kind=base: a town you stay in and ride out from. offers = what you can ride from it, by discipline: "
         "mtb: lift (lifts & shuttles), trails (trail centres and natural trails) · road: day, climbs, cobbles · gravel: day. "
         "category = its main discipline (sets the dot colour). "
         "kind=route: a multi-day route, one-way or loop (you move on each night); category = main surface; support = hotel | bikepacking | remote. "
         "season/best are month numbers (season wraps if start > end). elev = [low, high] m; refElev = where riding "
         "conditions are modelled. stats: km, days, climb (m) for routes. children = a few highlights (not every ride): "
         "kind area | park | climb | section, with a short note.")

MACROS = {"na": "North America", "eu": "Europe", "asia": "Asia", "oce": "Australia & New Zealand",
          "sa": "Latin America", "af": "Africa & Middle East"}
ZONES = {  # order = list order in the sidebar
    "alaska": ("Alaska & Yukon", "na"), "bc": ("Western Canada", "na"), "usw": ("US West & Rockies", "na"), "hawaii": ("Hawaii", "na"),
    "usc": ("Central & Eastern US", "na"), "ecan": ("Eastern Canada", "na"), "mexico": ("Mexico", "sa"), "andes": ("Andes", "sa"), "patagonia": ("Patagonia", "sa"),
    "uk": ("Britain", "eu"), "iceland": ("Iceland", "eu"), "nordic": ("Scandinavia & the Baltic", "eu"), "benelux": ("Belgium & Germany", "eu"),
    "france": ("France", "eu"), "alps": ("Switzerland & Austria", "eu"), "italy": ("Italy", "eu"), "slovenia": ("Slovenia", "eu"), "adriatic": ("Croatia", "eu"),
    "iberia": ("Spain, Portugal & Andorra", "eu"), "atlantic": ("Atlantic islands", "eu"),
    "africa": ("Africa", "af"), "mideast": ("Middle East", "af"),
    "caucasus": ("Türkiye & the Caucasus", "asia"),
    "centralasia": ("Central Asia", "asia"), "himalaya": ("Himalaya & Tibet", "asia"), "eastasia": ("Japan & Taiwan", "asia"), "seasia": ("Southeast Asia", "asia"),
    "aus": ("Australia", "oce"), "nz": ("New Zealand", "oce"),
}

def D(id, name, category, types, zone, country, region, lat, lon, elev, refElev, season, best, crowds, cost, guide,
      airport, terrain, pitch, children=None, stats=None, also=None, tags=None, weather=None, advisory=None):
    d = dict(id=id, name=name, category=category, types=types, tags=tags or [], also=also or [], country=country,
             region=region, zone=zone, lat=lat, lon=lon, elev=elev, refElev=refElev, season=season, best=best,
             crowds=crowds, cost=cost, guide=guide, airport=airport, terrain=terrain, pitch=pitch)
    if stats: d["stats"] = stats
    if weather: d["weather"] = weather
    if advisory: d["advisory"] = advisory
    if children: d["children"] = [dict(zip(("name", "kind", "lat", "lon", "note"), c)) for c in children]
    return d

def K(name, kind, lat, lon, note): return (name, kind, lat, lon, note)

