assert set(HIRE) == {d["id"] for d in DEST} and all(v[0] in ("easy", "limited", "byo") for v in HIRE.values())
assert set(BASES) | set(ROUTES) == {d["id"] for d in DEST} and not set(BASES) & set(ROUTES), "every destination must be a base or a route"
for d in DEST:
    for k in ("types", "also", "tags"): d.pop(k, None)
    d["hire"], d["hireNote"] = HIRE[d["id"]]
    if d["id"] in BASES:
        name, offers = BASES[d["id"]]
        assert d["category"] in offers, d["id"]
        d["kind"] = "base"; d["offers"] = offers
        if name: d["name"] = name
    else:
        d["kind"] = "route"; d["support"] = ROUTES[d["id"]]
        assert d.get("stats"), d["id"]

out = {"_about": ABOUT, "macros": MACROS, "zones": {k: {"name": n, "macro": m} for k, (n, m) in ZONES.items()}, "destinations": DEST}
ids = [d["id"] for d in DEST]; assert len(ids) == len(set(ids)), "duplicate ids"
assert all(d["zone"] in ZONES for d in DEST)
with open(os.path.join(ROOT, "data", "destinations.json"), "w") as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
from collections import Counter
print(len(DEST), "destinations", dict(Counter(d["kind"] for d in DEST)), dict(Counter(d["category"] for d in DEST)))
